-- 553: Foundation guard for WASSCE Social Studies sprint 3 beta batch (wassce-social-studies-sprint3-001).
-- Original BrillaPrep practice content; not official WAEC examination material.
-- Re-asserts the prod-canonical topic rows for subj_wassce_social on scratch
-- baselines; INSERT OR IGNORE no-ops on prod and on fresh baselines where the
-- rows already exist (migration 366 created them with the same ids, names and slugs).
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO exam_boards (id, name, code, full_name, region, website_url, is_active, display_order) VALUES ('board_waec', 'WAEC', 'WAEC', 'West African Examinations Council', 'West Africa', 'https://waecgh.org/', 1, 1);
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_gov', 'subj_wassce_social', NULL, 'Governance and democracy', 'wassce-p2-soc-gov', 'Explain how constitutional provisions and institutions promote democratic governance in Ghana.', 'Governance in Ghana rests on the 1992 Constitution, which establishes the Executive, Legislature and Judiciary, guarantees fundamental human rights, and provides for checks and balances, the rule of law and an independent Electoral Commission.', '["Three arms of government: Executive, Legislature, Judiciary", "Presidential term: four years, renewable once", "Rule of law: no person is above the law"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_civ', 'subj_wassce_social', NULL, 'Elections and civic life', 'wassce-p2-soc-civ', 'Analyse threats to peaceful elections and propose civic solutions that protect the democratic process.', 'Civic life covers the rights and responsibilities of citizens: voting from age eighteen, paying taxes, obeying the law, and the work of the Electoral Commission and the NCCE in keeping elections free, fair and peaceful.', '["Voting age in Ghana: 18 years", "By-election: fills a seat vacant between general elections", "Referendum: a popular vote on one national question"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_med', 'subj_wassce_social', NULL, 'Media and national development', 'wassce-p2-soc-med', 'Assess the roles the media play in education, accountability and national development.', 'The media inform, educate and entertain, act as a watchdog over those in power, and give citizens a platform for public discussion; misuse through fake news and bias can however incite conflict and slow development.', '["Media roles: inform, educate, entertain, watchdog", "Disinformation = false information spread with intent to deceive", "Ethics: accuracy, fairness, balance"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_mig', 'subj_wassce_social', NULL, 'Population and migration', 'wassce-p2-soc-mig', 'Evaluate the causes and consequences of rural-urban migration for sending and receiving communities.', 'Population studies cover the census, growth and structure of the population; migration is driven by push factors (rural poverty, few jobs) and pull factors (urban jobs and amenities), with effects on both sending and receiving areas.', '["Census interval: about every 10 years", "Push factors drive out; pull factors attract", "Dependency ratio = (young + elderly) ÷ working-age population"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_cul', 'subj_wassce_social', NULL, 'Culture and globalization', 'wassce-p2-soc-cul', 'Explain how Ghanaian cultural values can be preserved amid globalizing influences.', 'Culture is the total way of life of a people — material objects and non-material values, language and beliefs. Globalization spreads culture across borders, bringing both benefits and the risk of cultural erosion.', '["Culture = total way of life of a people", "Material culture = tangible objects; non-material = values and beliefs", "Cultural diffusion = spread of cultural traits between societies"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_edu', 'subj_wassce_social', NULL, 'Adolescent health and education', 'wassce-p2-soc-edu', 'Analyse the causes of teenage pregnancy and its consequences for girls’ education and life chances.', 'Adolescence (10–19 years) brings puberty, peer pressure and health risks; abstinence, assertiveness, a balanced diet and avoiding substance abuse protect health and keep young people in school.', '["Adolescence: 10–19 years (WHO)", "Abstinence: the surest protection against STIs and pregnancy", "HIV is not spread by casual contact"]', 6, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_eco', 'subj_wassce_social', NULL, 'Agriculture and the economy', 'wassce-p2-soc-eco', 'Explain the contribution of agriculture to employment, food security and industrial growth in Ghana.', 'Agriculture employs the largest share of Ghana’s labour force, supplies food, earns foreign exchange through cocoa and other cash crops, and feeds raw materials to agro-processing industries.', '["Agriculture: largest employer in Ghana", "Cash crop: grown for sale/export, e.g. cocoa", "Agro-processing adds value to raw produce"]', 7, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_env', 'subj_wassce_social', NULL, 'Environment and illegal mining', 'wassce-p2-soc-env', 'Evaluate the environmental and social effects of illegal mining and the measures available to control it.', 'Illegal small-scale mining (galamsey) pollutes rivers with silt and mercury, destroys forests and farms, and leaves deadly pits; control requires firm law enforcement, regulated small-scale mining zones and land reclamation.', '["Galamsey = illegal small-scale gold mining", "Effects: river pollution, deforestation, mercury contamination", "Renewable resources regenerate; minerals do not"]', 8, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_soc_emp', 'subj_wassce_social', NULL, 'Work and unemployment', 'wassce-p2-soc-emp', 'Propose and assess measures government can take to reduce unemployment among the youth.', 'Unemployment means being willing and able to work but unable to find a job; it may be seasonal, structural, frictional or cyclical, and is reduced through skills training, entrepreneurship support and investment that creates jobs.', '["Unemployed = willing and able to work but jobless", "Seasonal unemployment follows the farming calendar", "Entrepreneur = opportunity spotter and risk bearer"]', 9, '2026-08-04T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_553_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_553_guard;
INSERT INTO _migration_553_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'exam_wassce') AND EXISTS (SELECT 1 FROM exam_boards WHERE id = 'board_waec') AND EXISTS (SELECT 1 FROM subjects WHERE id = 'subj_wassce_social' AND exam_type_id = 'exam_wassce') AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_wassce_p2_soc_gov', 'topic_wassce_p2_soc_civ', 'topic_wassce_p2_soc_med', 'topic_wassce_p2_soc_mig', 'topic_wassce_p2_soc_cul', 'topic_wassce_p2_soc_edu', 'topic_wassce_p2_soc_eco', 'topic_wassce_p2_soc_env', 'topic_wassce_p2_soc_emp') AND t.subject_id = 'subj_wassce_social' AND s.exam_type_id = 'exam_wassce') = 9 THEN 1 ELSE 0 END;
DROP TABLE _migration_553_guard;
